    public bool enabled(RefCounted owner,Resource actor)=>_animation.sampled_value(actor,new[]{"structure_enabled"},Physics(owner).Call("_local",actor,Time(owner)).AsDouble(),_data.get_value(actor,"structure_enabled",false)).AsBool();
    public Vector3 physical_point(RefCounted controller,string owner,Vector3 point,Transform3D fallback){var endpoint=controller.Get("structure").AsGodotObject().Call("endpoint",owner,point).AsGodotDictionary();if(endpoint.Count>0){var state=Get(controller.Get("display_states").AsGodotDictionary(),owner,new Settings()).AsGodotDictionary();foreach(var item in Get(state,"destruction_fragments",new GArray()).AsGodotArray()){var fragment=item.AsGodotDictionary();if(fragment["id"].AsString()==endpoint["id"].AsString())return fragment["pose"].AsTransform3D()*endpoint["local"].AsVector3();}}return fallback*point;}
    public bool active(RefCounted owner){var runtime=Runtime(owner);return runtime!=null&&enabled(owner,Actor(runtime))&&Actor(runtime).GetMeta("structure_tool",false).AsBool();}
    public void draw(RefCounted owner)
    {
        var primary=Runtime(owner);if(primary==null)return;var gizmo=Gizmo(owner);var rect=Spatial(owner).Call("toolbar_rect",4).AsRect2();if(enabled(owner,Actor(primary))){gizmo.DrawRect(rect,new Color(active(owner)?"285c57":"152430"));gizmo.DrawString(ThemeDB.FallbackFont,rect.Position+new Vector2(6,18),"Joints J",HorizontalAlignment.Left,68,11,new Color("85d5c4"));}var controller=Physics(owner);var model=Model(owner);var lens=Camera(owner);double time=Time(owner);
        foreach(var value in model.Get("actors").AsGodotArray()){var actor=value.As<Resource>();if(!enabled(owner,actor)||!_data.get_value(actor,"structure_overlay",true).AsBool())continue;string id=actor.Get("id").AsString();var state=State(owner,id);var pose=Pose(owner,id);var structural=Get(state,"structural",new Settings()).AsGodotDictionary();if(!lens.IsPositionBehind(pose.Origin)){var color=new Color(Get(structural,"supported",false).AsBool()?"83ddaa":"ffad68");var point=Project(owner,pose.Origin);if(_data.get_value(actor,"structure_role",0).AsInt32()!=0)gizmo.DrawRect(new Rect2(point-new Vector2(5,5),new Vector2(10,10)),color,false,2);else gizmo.DrawCircle(point,4,color,false,1.5f);}var links=Get(_animation.sampled_values(actor,controller.Call("_local",actor,time).AsDouble()),"structure_connections",new Settings()).AsGodotDictionary();foreach(var entry in links){string key=entry.Key.AsString();var link=entry.Value.AsGodotDictionary();var target=model.Call("actor_for_id",link["target"].AsString()).As<Resource>();if(target==null)continue;var a=physical_point(controller,id,link["pivot"].AsVector3(),pose);var b=physical_point(controller,target.Get("id").AsString(),link["target_pivot"].AsVector3(),Pose(owner,target.Get("id").AsString()));if(lens.IsPositionBehind(a)||lens.IsPositionBehind(b))continue;var runtime=Get(Get(structural,"links",new Settings()).AsGodotDictionary(),key,new Settings()).AsGodotDictionary();float used=(float)Math.Clamp(Get(runtime,"utilization",0).AsDouble(),0,1);var color=new Color("78dba7").Lerp(new Color("ff685e"),used);var pa=Project(owner,a);var pb=Project(owner,b);if(Get(runtime,"broken",false).AsBool()||!Get(link,"enabled",true).AsBool()){color=new Color("ff685e");gizmo.DrawDashedLine(pa,pb,color,1.5f,5);}else gizmo.DrawLine(pa,pb,color,2,true);gizmo.DrawCircle(Project(owner,(a+b)*.5f),5,color);if(active(owner)&&actor==Actor(primary)&&key==actor.GetMeta("structure_selected","").AsString()){gizmo.DrawCircle(pa,8,new Color("ffd078"),false,2);gizmo.DrawCircle(pb,6,new Color("80bdff"),false,2);var direction=pose.Basis*Basis.FromEuler(link["orientation"].AsVector3()*(Mathf.Pi/180))*Vector3.Up*.35f;var end=Project(owner,a+direction);gizmo.DrawLine(pa,end,new Color("90d3ff"),2,true);gizmo.DrawCircle(end,5,new Color("90d3ff"));}}}
        if(active(owner))gizmo.DrawString(ThemeDB.FallbackFont,new Vector2(12,78),"Approximate loads · Drag endpoints / direction · Ctrl: snap · Esc: exit",HorizontalAlignment.Left,-1,12,new Color("85d5c4"));
    }
    public void cancel(RefCounted owner){var actor=owner.Get("actor").As<Resource>();var before=owner.Get("before").AsGodotDictionary();if(actor!=null&&before.Count>0){actor.Set("values",_data.copy_value(before));actor.Get("animation_previews").AsGodotDictionary().Clear();actor.EmitChanged();Model(owner).EmitSignal("changed");}owner.Set("before",new Settings());}
    private static Vector3? PlaneHit(RefCounted owner,Settings ray)=>owner.Get("plane").AsPlane().IntersectsRay(ray["origin"].AsVector3(),ray["direction"].AsVector3());
    public bool handle_event(RefCounted owner,InputEvent input)
