        var runtime=Runtime(owner);if(runtime==null||!enabled(owner,Actor(runtime)))return false;var actor=Actor(runtime);var gizmo=Gizmo(owner);var spatial=Spatial(owner);var model=Model(owner);if(input is InputEventKey toggle&&toggle.Pressed&&!toggle.Echo&&toggle.Keycode==Key.J&&gizmo.HasFocus()||input is InputEventMouseButton tool&&tool.ButtonIndex==MouseButton.Left&&tool.Pressed&&spatial.Call("toolbar_rect",4).AsRect2().HasPoint(tool.Position)){actor.SetMeta("structure_tool",!active(owner));gizmo.GrabFocus();return true;}if(!active(owner))return false;if(input is InputEventKey escape&&escape.Pressed&&escape.Keycode==Key.Escape){cancel(owner);actor.SetMeta("structure_tool",false);return true;}string id=actor.GetMeta("structure_selected","").AsString();double sample=actor.Get("animation_time").AsDouble();var values=_animation.sampled_values(actor,double.IsNaN(sample)?0:sample);var links=Get(values,"structure_connections",new Settings()).AsGodotDictionary();var link=Get(links,id,new Settings()).AsGodotDictionary();if(input is InputEventMouseButton wheel&&wheel.ShiftPressed&&wheel.Pressed&&(wheel.ButtonIndex is MouseButton.WheelUp or MouseButton.WheelDown)&&link.Count>0){_structure.set_value(model,actor,id,"strength",Math.Max(.001,link["strength"].AsDouble()*(wheel.ButtonIndex==MouseButton.WheelUp?1.1:1/1.1)),false);return true;}
        if(input is InputEventMouseButton click&&click.ButtonIndex==MouseButton.Left){if(click.Pressed){float best=14;var chosen=new Settings();var pose=runtime.Call("remote_transform").AsTransform3D();foreach(var entry in links){var candidate=entry.Value.AsGodotDictionary();var target=model.Call("actor_for_id",candidate["target"].AsString()).As<Resource>();if(target==null)continue;var other=Pose(owner,target.Get("id").AsString());var a=pose*candidate["pivot"].AsVector3();var points=new Settings{["pivot"]=a,["target_pivot"]=other*candidate["target_pivot"].AsVector3(),["orientation"]=a+pose.Basis*Basis.FromEuler(candidate["orientation"].AsVector3()*(Mathf.Pi/180))*Vector3.Up*.35f};foreach(var point in points){float distance=Project(owner,point.Value.AsVector3()).DistanceTo(click.Position);if(distance<best){best=distance;chosen=new Settings{["id"]=entry.Key,["field"]=point.Key,["point"]=point.Value};}}}if(chosen.Count==0)return false;owner.Set("actor",actor);owner.Set("selected",chosen["id"]);owner.Set("field",chosen["field"]);actor.SetMeta("structure_selected",chosen["id"]);owner.Set("before",_data.copy_value(actor.Get("values")));var pointValue=chosen["point"].AsVector3();owner.Set("plane",new Plane(Camera(owner).GlobalBasis.Z,pointValue));var hit=PlaneHit(owner,spatial.Call("_ray",click.Position).AsGodotDictionary());owner.Set("offset",hit.HasValue?pointValue-hit.Value:Vector3.Zero);gizmo.GrabFocus();return true;}var before=owner.Get("before").AsGodotDictionary();if(before.Count>0){var target=owner.Get("actor").As<Resource>();string selected=owner.Get("selected").AsString(),field=owner.Get("field").AsString();var path=new[]{"structure_connections",selected,field};double time=target.Get("animation_time").AsDouble();var final=_animation.sampled_value(target,path,double.IsNaN(time)?0:time,_animation.value_at_path(target,path));target.Set("values",before);owner.Set("before",new Settings());_structure.set_value(model,target,selected,field,final,false);return true;}}
